/**
 * Correlatives: a complete 6 × 6 grid, written `determiner-concept`.
 *
 * All 36 stored forms are generated by concatenation with a hyphen, and the
 * grid has no gaps.
 */

export const DETERMINERS = ['ki', 'eli', 'ola', 'toda', 'nuna', 'somi'] as const;
export type Determiner = (typeof DETERMINERS)[number];

export const CONCEPTS = ['coda', 'pago', 'krono', 'nela', 'modo', 'kasa'] as const;
export type Concept = (typeof CONCEPTS)[number];

export const DETERMINER_SENSE: Readonly<Record<Determiner, string>> = {
  ki: 'interrogative',
  eli: 'proximal',
  ola: 'distal',
  toda: 'universal',
  nuna: 'negative',
  somi: 'existential',
};

export const CONCEPT_SENSE: Readonly<Record<Concept, string>> = {
  coda: 'thing',
  pago: 'place',
  krono: 'time',
  nela: 'person',
  modo: 'manner',
  kasa: 'reason',
};

export function spellCorrelative(determiner: Determiner, concept: Concept): string {
  return `${determiner}-${concept}`;
}

export interface CorrelativeCell {
  form: string;
  determiner: Determiner;
  concept: Concept;
}

/** The full grid, in the order the lexicon stores it: determiner-major. */
export function correlativeGrid(): CorrelativeCell[] {
  return DETERMINERS.flatMap((determiner) =>
    CONCEPTS.map((concept) => ({
      form: spellCorrelative(determiner, concept),
      determiner,
      concept,
    })),
  );
}

/** Split a correlative back into its parts, or `null` if it is not one. */
export function parseCorrelative(form: string): CorrelativeCell | null {
  const at = form.indexOf('-');
  if (at < 0) return null;
  const determiner = form.slice(0, at);
  const concept = form.slice(at + 1);
  if (!(DETERMINERS as readonly string[]).includes(determiner)) return null;
  if (!(CONCEPTS as readonly string[]).includes(concept)) return null;
  return {
    form,
    determiner: determiner as Determiner,
    concept: concept as Concept,
  };
}
